int run_or_verify_file(const std::string& cmd, const std::string& path, bool verbose) {
    if (path.size() >= 4 && path.substr(path.size() - 4) == ".qcy") return run_or_verify_qcy_file(cmd, path, verbose);
    if (!std::filesystem::exists(path)) return 1;
    std::string src = read_file_text(path);
    if (!singular::constitution::SingularConstitutionalCompiler::check_file_line_limit(path, src).code.empty()) return 1;
    auto ast = cycraft::omega::language::CyCraftParser::parse_source(src, path);
    auto sema = cycraft::omega::language::CyCraftSemanticAnalyzer::check_module(ast);
    if (!sema.ok) return 1;
    return cycraft::omega::runtime::CyCraftExecutionEngine::compile_and_execute(ast, cycraft::omega::compiler::CyCraftCausalIrBuilder::lower_to_ccir(ast, sema)).canary_integrity_verified ? 0 : 1;
}
